import React, { useState, useEffect, useCallback, useRef } from 'react';
import { supabase } from '../../lib/supabase';
import { fmtCompact, fmtDate, isValidTikTokMusicUrl } from '../../utils/format';
import { humanizeError } from '../../utils/errors';
import { resolveMusicUrl, resolveErrorMessage } from '../../utils/musicLink';
import { useToast } from '../shared/Toast';
import { ChevronIcon, MusicIcon } from '../shared/Icon';
import { campaignBaseLabel } from '../../utils/campaignLabel';
import ReadError from '../shared/ReadError';
import SubmitButton from '../shared/SubmitButton';
import { useLoadState } from '../../hooks/useLoadState';
import Refreshing from '../shared/Refreshing';

/**
 * components/creator/MissingSounds.js - the "Missing sounds" backlog on the creator mobile
 * page. Lists deliverables carrying no contracted sound and lets her supply one per row.
 *
 * A contracted sound is the track the AGENCY asked for: the brief half of the compliance check
 * the agency dashboard renders, against the audio TikTok reports.
 *
 * @invariant the sound is never JOINED here: no yt_dlp_metadata, no music_url, no
 *            per-deliverable track. A row shows the campaign's name and nothing more.
 * @gotcha rows are titled by campaign display name, so a single-deliverable campaign states the
 *         sound the post USED. She can copy that into the brief field, which makes the row
 *         match without anything being verified and overstates Sounds Checked. That trade is a
 *         standing decision; do NOT "fix" it by trimming the sound off client-side.
 * @gotcha the open row is mirrored to sessionStorage: iOS discards a backgrounded tab's React
 *         state, and she leaves the app for every row to find the answer.
 * @see CLAUDE.md (Sounds Checked KPI)
 */

const OPEN_KEY = 'nys_missing_sound_open';
const EXPAND_KEY = 'nys_missing_sound_expanded';

/** Undo window for a "no sound" / "can't find it" answer, in ms. */
const UNDO_MS = 7000;

/**
 * The two answers that are not a link. Padded to a real thumb target without
 * gaining any button chrome: this is the destructive path, so it must be
 * hittable on purpose and hard to hit by accident.
 */
const OUT_BTN = {
  background: 'none', border: 'none', font: 'inherit', cursor: 'pointer',
  padding: '8px 0', fontSize: 13, color: 'var(--muted)', textDecoration: 'underline',
  textUnderlineOffset: 3, textDecorationColor: 'var(--border2)',
};

/**
 * Compact view count. 171912 -> "172K".
 *
 * A thin wrapper over the one shared formatter, kept only for the null contract below. It was
 * local until P42: three other screens compacted the same numbers and no two agreed.
 * @see utils/format.js fmtCompact
 */
function fmtViews(n) {
  // null stays null here, not an em dash: the caller renders NOTHING for an unknown view
  // count rather than a placeholder beside a sound the creator is being asked about.
  if (n == null) return null;
  return fmtCompact(n);
}

/**
 * Pull the first http(s) URL out of pasted text.
 *
 * @gotcha She is pasting out of a chat, so the clipboard routinely carries the
 *         agency's sentence around the link ("use this one pls <url> by friday").
 *         Rejecting that as invalid would read as the field being broken.
 */
function firstUrl(text) {
  const m = String(text || '').match(/https?:\/\/[^\s<>"']+/);
  return m ? m[0].replace(/[.,)]+$/, '') : String(text || '').trim();
}

/** How many logged rows render before "Show older". 82 rows is a long scroll on a phone. */
export const LOGGED_PAGE = 12;

/**
 * The answer she gave, as one line of text, for the collapsed row she is scanning.
 *
 * @gotcha text and not an anchor. The collapsed row is a `role="button"`, and a link inside it
 *         is `nested-interactive`.
 */
function storedAnswerText(row) {
  if (row.music_url) return row.music_url;
  if (row.music_brief_status === 'none_given') return 'They didn\u2019t send one';
  if (row.music_brief_status === 'unrecoverable') return 'Can\u2019t find it';
  return '';
}

/**
 * The answer she gave, in the words she gave it in.
 *
 * @gotcha this is HER stored brief, never the sound the video used. The two are different
 *         facts and the second one is the thing this whole screen exists not to show.
 */
function StoredAnswer({ row }) {
  if (row.music_url) {
    return (
      <a
        href={row.music_url}
        target="_blank"
        rel="noopener noreferrer"
        style={{ color: 'var(--white)', wordBreak: 'break-all' }}
      >
        {row.music_url}
      </a>
    );
  }
  if (row.music_brief_status === 'none_given') return <span style={{ color: 'var(--white)' }}>They didn&rsquo;t send one</span>;
  if (row.music_brief_status === 'unrecoverable') return <span style={{ color: 'var(--white)' }}>Can&rsquo;t find it</span>;
  return null;
}

/**
 * One sound row, in either list. Collapsed it is a recognition cue; expanded it is a single
 * input plus the two ways of answering that are not a link.
 *
 * In the logged list it also shows the answer she gave, because that is the thing being
 * corrected and she cannot tell a wrong sound from a right one without it. That is not the
 * banned join: it is HER stored brief, not the sound the video used.
 *
 * @param {object} row - deliverable joined to its brand, thumbnail and views.
 * @param {boolean} open - only one row is open at a time (parent-owned).
 * @param {boolean} logged - true in the logged list: the row already carries an answer.
 * @param {function} onAnswer - (rowId, label, previous) after a successful write.
 */
function SoundRow({ row, open, onOpen, onAnswer, logged = false }) {
  const [value, setValue] = useState('');
  const [saving, setSaving] = useState(false);
  // Set only when the link itself is the problem (usually already expired),
  // which is the one case she has to hear about because nothing can be saved.
  const [resolveError, setResolveError] = useState(null);
  const toast = useToast();
  const url = firstUrl(value);
  const valid = isValidTikTokMusicUrl(url);
  const showError = value.trim() !== '' && !valid;

  /**
   * @gotcha a replace writes BOTH columns, always. Pasting a link over a "they didn't send one"
   *         leaves `music_brief_status` set otherwise, and the agency dashboard then reads a
   *         deliverable that is briefed and simultaneously declared unbriefable.
   */
  async function write(patch, label) {
    setSaving(true);
    const full = logged ? { music_url: null, music_brief_status: null, ...patch } : patch;
    const { error } = await supabase
      .from('campaign_deliverables').update(full).eq('id', row.id);
    setSaving(false);
    if (error) { toast.error(humanizeError(error)); return; }
    onAnswer(row.id, label, logged
      ? { music_url: row.music_url ?? null, music_brief_status: row.music_brief_status ?? null }
      : null, full);
  }

  /**
   * Save a pasted sound link, resolved to its permanent form first.
   *
   * @gotcha She pastes what the agency sent, which is usually a share link that
   *         TikTok expires within days. Storing that verbatim is why 30 rows
   *         ended up counting as briefed while being impossible to check. The
   *         resolve is silent on success: she is not asked to confirm a track
   *         name, both because the app can determine it and because naming the
   *         sound on this screen is what the whole design avoids.
   * @see utils/musicLink.js
   */
  async function saveSound() {
    setSaving(true);
    const res = await resolveMusicUrl(value);
    if (!res.ok) {
      setSaving(false);
      setResolveError(resolveErrorMessage(res.reason));
      return;
    }
    setResolveError(null);
    // No reset here: write() raises the same flag on its next statement, so lowering it
    // first only says the row is idle for as long as React takes to batch the two.
    await write({ music_url: res.canonical_url }, logged ? 'Sound replaced' : 'Sound saved');
  }

  const posted = !!row.actual_post_date;
  const views = fmtViews(row.views);

  return (
    <div style={{ borderTop: '1px solid var(--border)' }}>
      <div
        role="button"
        tabIndex={0}
        aria-expanded={open}
        onClick={() => onOpen(open ? null : row.id)}
        onKeyDown={e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); onOpen(open ? null : row.id); } }}
        style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '12px 2px', cursor: 'pointer' }}
      >
        {/* 9:16 crop at thumb scale. A missing thumbnail keeps the slot rather
            than collapsing it, so the rows stay on one left edge. */}
        <div style={{
          width: 38, height: 50, flexShrink: 0, borderRadius: 5, overflow: 'hidden',
          background: 'var(--surface2)', display: 'flex', alignItems: 'center', justifyContent: 'center',
        }}>
          {row.thumbnail_url
            ? <img src={row.thumbnail_url} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block' }} />
            : <MusicIcon size={14} style={{ color: 'var(--dim)' }} />}
        </div>

        <div style={{ minWidth: 0, flex: 1 }}>
          <div title={row.brand} style={{
            fontSize: 14, fontWeight: 600, color: 'var(--white)',
            overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
          }}>
            {row.brand}
          </div>
          <div style={{ fontSize: 11, color: 'var(--dim)', marginTop: 3 }}>
            {posted
              ? [fmtDate(row.actual_post_date, 'MMM d'), views && `${views} views`].filter(Boolean).join(' · ')
              : ['Not posted yet', row.contracted_post_date && `due ${fmtDate(row.contracted_post_date, 'MMM d')}`].filter(Boolean).join(' · ')}
          </div>
          {/* Plain text, never the anchor: an anchor inside a role="button" row is a real
              nested-interactive violation. The open panel carries the clickable one. */}
          {logged && (
            <div title={storedAnswerText(row)} style={{
              fontSize: 11, color: 'var(--muted)', marginTop: 4,
              overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
            }}>
              {storedAnswerText(row)}
            </div>
          )}
        </div>

        <ChevronIcon
          size={12}
          style={{
            color: 'var(--dim)', flexShrink: 0,
            transform: open ? 'rotate(90deg)' : 'none',
            transition: 'transform 0.18s cubic-bezier(0.2,0,0,1)',
          }}
        />
      </div>

      {open && (
        <div style={{ padding: '2px 2px 16px 52px' }}>
          {logged && (
            <div style={{ fontSize: 12, color: 'var(--muted)', marginBottom: 12, lineHeight: 1.5 }}>
              <div style={{ color: 'var(--dim)', marginBottom: 3 }}>You logged</div>
              <StoredAnswer row={row} />
            </div>
          )}
          <label
            htmlFor={`snd-${row.id}`}
            style={{ display: 'block', fontSize: 12, color: 'var(--muted)', marginBottom: 8 }}
          >
            {logged ? 'Paste the one they actually asked for. It replaces the answer above.'
                    : 'Which sound did they ask for?'}
          </label>
          <input
            id={`snd-${row.id}`}
            className="form-input"
            type="url"
            inputMode="url"
            value={value}
            onChange={e => { setValue(e.target.value); setResolveError(null); }}
            placeholder="Paste the TikTok sound link"
            maxLength={500}
            autoComplete="off"
            autoCorrect="off"
            autoCapitalize="off"
            spellCheck={false}
            style={{ width: '100%', boxSizing: 'border-box', fontSize: 16 }}
          />
          {showError && (
            <div style={{ marginTop: 6, fontSize: 12, color: 'var(--red)', lineHeight: 1.4 }}>
              That is not a TikTok sound link. It looks like tiktok.com/music/…
            </div>
          )}
          {resolveError && !showError && (
            <div style={{ marginTop: 6, fontSize: 12, color: 'var(--red)', lineHeight: 1.4 }}>
              {resolveError}
            </div>
          )}

          <SubmitButton saving={saving} className="btn btn-primary" disabled={!valid || saving} onClick={saveSound} style={{ width: '100%', marginTop: 12, fontSize: 15, fontWeight: 700 }}>{logged ? 'Replace sound' : 'Save sound'}</SubmitButton>

          {/* Two outs, as sentence-case text: they are the exception, and giving
              them button weight invites them over the actual task. Deliberately
              NOT .btn, which uppercases and letterspaces, so a quiet escape
              hatch rendered as loud as the primary CTA beside it. */}
          <div style={{ display: 'flex', gap: 22, marginTop: 12 }}>
            <button type="button" disabled={saving} style={OUT_BTN}
              onClick={() => write({ music_brief_status: 'none_given' }, 'Marked as no sound sent')}>
              They didn&rsquo;t send one
            </button>
            <button type="button" disabled={saving} style={OUT_BTN}
              onClick={() => write({ music_brief_status: 'unrecoverable' }, "Marked as can't find it")}>
              Can&rsquo;t find it
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

/**
 * The Missing sounds section. Renders nothing at all when the backlog is empty:
 * an empty-state panel for a chore that is already done is pure chrome.
 *
 * @param {function} onCountChange - optional; reports the outstanding count so
 *        the host page can lay out around a section that may not render.
 */
export default function MissingSounds({ onCountChange, creatorName }) {
  const [rows, setRows] = useState([]);
  const { loading, refreshing, begin, end } = useLoadState();
  // The third state. The section renders NOTHING when the backlog is empty, so a refused read
  // took the whole chore off her phone: no list, no count, no sign anything was asked.
  const [loadError, setLoadError] = useState(null);
  const [expanded, setExpanded] = useState(() => sessionStorage.getItem(EXPAND_KEY) === '1');
  const [openId, setOpenId] = useState(() => sessionStorage.getItem(OPEN_KEY) || null);
  // The logged list: what she has already answered, so a wrong sound has somewhere to be
  // fixed. Its own read and its own error, because the backlog being empty is the live state
  // and a section that renders on the backlog alone is invisible exactly when this is needed.
  const [logged, setLogged] = useState([]);
  const [loggedError, setLoggedError] = useState(null);
  const [loggedOpen, setLoggedOpen] = useState(false);
  const [loggedAll, setLoggedAll] = useState(false);
  // { id, label, patch } for the row currently inside its undo window.
  const [undo, setUndo] = useState(null);
  const undoTimer = useRef(null);
  const toast = useToast();

  const load = useCallback(async () => {
    begin();
    setLoadError(null);
    const { data, error } = await supabase
      .from('campaign_deliverables')
      .select(`id, contracted_post_date, actual_post_date, campaign_id,
               campaign:campaigns(display_name, agency:agencies(name)),
               stats:video_stats(thumbnail_url, views)`)
      .is('music_url', null)
      .is('music_brief_status', null);
    if (error) { setLoadError(error); setRows([]); end(); return; }
    const mapped = (data || []).map(d => ({
      id: d.id,
      contracted_post_date: d.contracted_post_date,
      actual_post_date: d.actual_post_date,
      brand: d.campaign?.display_name || campaignBaseLabel(d.campaign?.agency?.name, creatorName),
      thumbnail_url: (d.stats || [])[0]?.thumbnail_url || null,
      views: (d.stats || [])[0]?.views ?? null,
    }));
    // Posted first, newest at the top: those are the ones she can recognise and
    // answer now. Unposted rows have no thumbnail and often no brief to find
    // yet, so they sink rather than heading a list she is meant to drain.
    mapped.sort((a, b) => {
      if (!!a.actual_post_date !== !!b.actual_post_date) return a.actual_post_date ? -1 : 1;
      if (a.actual_post_date) return b.actual_post_date.localeCompare(a.actual_post_date);
      return String(a.contracted_post_date || '').localeCompare(String(b.contracted_post_date || ''));
    });
    setRows(mapped);
    end();
  }, [creatorName, begin, end]);

  /**
   * Everything she has answered, either way.
   *
   * @invariant the same column list as the backlog read, and no wider. Adding the sound the
   *            video used here would defeat the standing rule from the other direction: she
   *            would be correcting a brief while looking at the answer.
   */
  const loadLogged = useCallback(async () => {
    setLoggedError(null);
    const { data, error } = await supabase
      .from('campaign_deliverables')
      .select(`id, contracted_post_date, actual_post_date, campaign_id, music_url, music_brief_status,
               campaign:campaigns(display_name, agency:agencies(name)),
               stats:video_stats(thumbnail_url, views)`)
      .or('music_url.not.is.null,music_brief_status.not.is.null');
    if (error) { setLoggedError(error); setLogged([]); return; }
    const mapped = (data || []).map(d => ({
      id: d.id,
      contracted_post_date: d.contracted_post_date,
      actual_post_date: d.actual_post_date,
      music_url: d.music_url,
      music_brief_status: d.music_brief_status,
      brand: d.campaign?.display_name || campaignBaseLabel(d.campaign?.agency?.name, creatorName),
      thumbnail_url: (d.stats || [])[0]?.thumbnail_url || null,
      views: (d.stats || [])[0]?.views ?? null,
    }));
    // Newest posted first: recency is what she has in mind whether she noticed the mistake
    // herself or an agency named the campaign for her.
    mapped.sort((a, b) => String(b.actual_post_date || '').localeCompare(String(a.actual_post_date || '')));
    setLogged(mapped);
  }, [creatorName]);

  useEffect(() => { load(); }, [load]);
  useEffect(() => { loadLogged(); }, [loadLogged]);
  useEffect(() => { if (onCountChange) onCountChange(rows.length); }, [rows.length, onCountChange]);
  useEffect(() => { sessionStorage.setItem(EXPAND_KEY, expanded ? '1' : '0'); }, [expanded]);
  useEffect(() => {
    if (openId) sessionStorage.setItem(OPEN_KEY, openId);
    else sessionStorage.removeItem(OPEN_KEY);
  }, [openId]);
  useEffect(() => () => clearTimeout(undoTimer.current), []);

  /**
   * @gotcha The row is dropped from the list immediately and the undo line
   *         replaces the whole section header for UNDO_MS. She is on a phone
   *         answering 32 of these; a mis-tap on "They didn't send one" with no
   *         way back writes a wrong compliance fact she cannot see again.
   */
  function handleAnswer(id, label, previous, applied) {
    if (previous) {
      // A CORRECTION. The row stays where it is with its new value: a correction is still an
      // answer, so the outstanding count does not move and the agency's Sounds Checked rate
      // does not dip while she fixes it.
      setLogged(prev => prev.map(r => (r.id === id ? { ...r, ...applied } : r)));
    } else {
      setRows(prev => prev.filter(r => r.id !== id));
      // It has just become something she has logged, so it belongs in that list now.
      loadLogged();
    }
    setOpenId(null);
    clearTimeout(undoTimer.current);
    setUndo({ id, label, previous });
    undoTimer.current = setTimeout(() => setUndo(null), UNDO_MS);
  }

  /**
   * @gotcha undoing a CORRECTION puts the previous answer back, it does not unanswer the row.
   *         Clearing both columns there would push a deliverable she had already answered into
   *         the backlog, which is the one thing the confirmed design says must not happen.
   */
  async function revert() {
    const target = undo;
    if (!target) return;
    clearTimeout(undoTimer.current);
    setUndo(null);
    const patch = target.previous || { music_url: null, music_brief_status: null };
    const { error } = await supabase
      .from('campaign_deliverables').update(patch).eq('id', target.id);
    if (error) { toast.error(humanizeError(error)); return; }
    load();
    loadLogged();
  }

  if (loading) return null;

  // Error before empty, and before the render-nothing shortcut below: "no outstanding sounds"
  // is a claim, and a read that did not answer has not earned it.
  if (loadError) {
    return (
      <div style={{ marginTop: 32 }}>
        <div style={{ fontSize: 11, color: 'var(--muted)', letterSpacing: '0.1em', textTransform: 'uppercase', fontWeight: 700, marginBottom: 10 }}>
          Missing sounds
        </div>
        <ReadError error={loadError} onRetry={load} />
      </div>
    );
  }

  // Nothing outstanding, nothing logged, nothing failed: no chore, no section. The test is
  // both lists, not the backlog: a drained backlog is the ordinary state and this section is
  // also the only place a wrong sound can be corrected.
  if (rows.length === 0 && logged.length === 0 && !loggedError && !undo) return null;

  // With nothing outstanding there is no backlog to head. Drawing "Missing sounds" and a
  // 20px orange 0 over an empty list spends the screen's one loud element on the absence of
  // work, and the sub-line under it tells her to paste links she does not owe.
  const hasBacklog = rows.length > 0;

  return (
    <div style={{ marginTop: 32 }}>
      {/* The whole section vanishes on `if (loading) return null` above, which is why undoing
          an answer used to take it off the dashboard. A refetch keeps it and says so. */}
      <Refreshing on={refreshing} />
      {hasBacklog && (<>
      <div
        role="button"
        tabIndex={0}
        aria-expanded={expanded}
        onClick={() => setExpanded(v => !v)}
        onKeyDown={e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setExpanded(v => !v); } }}
        style={{ display: 'flex', alignItems: 'baseline', gap: 10, cursor: 'pointer' }}
      >
        <div style={{ fontSize: 11, color: 'var(--muted)', letterSpacing: '0.1em', textTransform: 'uppercase', fontWeight: 700 }}>
          Missing sounds
        </div>
        <div style={{ fontFamily: 'var(--font-display)', fontSize: 20, lineHeight: 1, letterSpacing: 1, color: 'var(--orange)' }}>
          {rows.length}
        </div>
        <ChevronIcon
          size={12}
          style={{
            color: 'var(--dim)', marginLeft: 'auto', alignSelf: 'center',
            transform: expanded ? 'rotate(90deg)' : 'none',
            transition: 'transform 0.18s cubic-bezier(0.2,0,0,1)',
          }}
        />
      </div>

      <div style={{ fontSize: 12, color: 'var(--dim)', marginTop: 4, lineHeight: 1.4 }}>
        Paste the sound link each agency sent you.
      </div>

      </>)}

      {/* Outside the backlog header on purpose: a CORRECTION is undoable too, and its undo
          has to appear on a screen with nothing outstanding to head. */}
      {undo && (
        <div style={{
          display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 12,
          marginTop: hasBacklog ? 10 : 0, padding: '9px 12px', borderRadius: 8,
          border: '1px solid var(--border)', background: 'var(--surface)',
        }}>
          <span style={{ fontSize: 12, color: 'var(--muted)' }}>{undo.label}</span>
          <button className="btn btn-ghost btn-sm" onClick={revert} style={{ padding: 0, fontSize: 12, color: 'var(--orange)', fontWeight: 700 }}>
            Undo
          </button>
        </div>
      )}

      {expanded && rows.length > 0 && (
        <div style={{ marginTop: 10 }}>
          {rows.map(r => (
            <SoundRow
              key={r.id}
              row={r}
              open={openId === r.id}
              onOpen={setOpenId}
              onAnswer={handleAnswer}
            />
          ))}
        </div>
      )}

      {/* The logged list. Collapsed by default and in the muted register throughout: this is
          a correction, not an achievement, so nothing here competes with the orange count
          above it. */}
      {loggedError ? (
        <div style={{ marginTop: 16 }}>
          <ReadError error={loggedError} onRetry={loadLogged} />
        </div>
      ) : logged.length > 0 && (
        <div style={{ marginTop: rows.length > 0 ? 18 : 12 }}>
          <div
            role="button"
            tabIndex={0}
            aria-expanded={loggedOpen}
            onClick={() => setLoggedOpen(v => !v)}
            onKeyDown={e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setLoggedOpen(v => !v); } }}
            style={{ display: 'flex', alignItems: 'center', gap: 8, cursor: 'pointer', padding: '4px 0' }}
          >
            <span style={{ fontSize: 12, color: 'var(--muted)' }}>
              Sounds you&rsquo;ve logged
            </span>
            <span style={{ fontSize: 12, color: 'var(--dim)' }}>{logged.length}</span>
            <ChevronIcon
              size={11}
              style={{
                color: 'var(--dim)', marginLeft: 'auto',
                transform: loggedOpen ? 'rotate(90deg)' : 'none',
                transition: 'transform 0.18s cubic-bezier(0.2,0,0,1)',
              }}
            />
          </div>

          {loggedOpen && (
            <div>
              {(loggedAll ? logged : logged.slice(0, LOGGED_PAGE)).map(r => (
                <SoundRow
                  key={r.id}
                  row={r}
                  logged
                  open={openId === r.id}
                  onOpen={setOpenId}
                  onAnswer={handleAnswer}
                />
              ))}
              {!loggedAll && logged.length > LOGGED_PAGE && (
                <button type="button" onClick={() => setLoggedAll(true)} style={{ ...OUT_BTN, marginTop: 4 }}>
                  Show older ({logged.length - LOGGED_PAGE})
                </button>
              )}
            </div>
          )}
        </div>
      )}
    </div>
  );
}
