/**
 * utils/musicLink.js: the one place a pasted sound link becomes a stored one.
 *
 * TikTok share links (`tiktok.com/t/ZP...`, `vm.tiktok.com/...`) are redirects that expire
 * within days. Stored raw they become a dead reference to a sound nobody can name, and the
 * deliverable counts as briefed while being impossible to verify against anything.
 *
 * So nothing writes `campaign_deliverables.music_url` from raw user input. It goes through
 * `resolveMusicUrl` first, which hands back the permanent `tiktok.com/music/<slug>-<id>` form.
 * A CHECK constraint on the column rejects the share forms outright.
 *
 * @gotcha The browser cannot follow the redirect itself: TikTok sends no CORS headers, so the
 *         resolve has to run server-side via the edge function.
 * @gotcha Resolution must happen AT ENTRY. Doing it on a later batch pass is not a slower fix
 *         but no fix at all, since by then the redirect is gone.
 * @see supabase/functions/resolve-music-link, scripts/music-resolve.js
 */
import { supabase } from '../lib/supabase';

/** Reasons a resolve can fail, in the creator's words. */
const REASONS = {
  expired: 'That link has expired. Ask them for the sound page link instead.',
  no_link: 'No link found in there.',
  not_tiktok: 'That is not a TikTok link.',
  not_a_sound: 'That link does not point at a sound.',
  unreachable: 'Could not check that link just now. Try again in a moment.',
};

/**
 * True for the TikTok share forms that expire.
 *
 * @gotcha Deliberately STRICTER than `chk_music_url_not_share_link`, not equal
 *         to it: the SQL requires the `//` before `vm.tiktok.com`, this also
 *         refuses a scheme-less paste, which is what a creator gets when she
 *         copies from the app. Making the two identical would open that hole.
 *         The asymmetry is pinned by utils/__tests__/schemaMirrors.test.js so it
 *         cannot be flattened by someone tidying up.
 */
export function isShareLink(url) {
  return /(?:\/t\/[A-Za-z0-9]+|(?:^|\/\/)(?:vm|vt)\.tiktok\.com\/)/i.test(String(url || ''));
}

/** The music id out of a permanent sound URL, or null. */
export function extractMusicId(url) {
  const m = String(url || '').match(/\/music\/[^/?#]*-(\d{15,20})(?:[/?#]|$)/);
  return m ? m[1] : null;
}

/** Turn a failure reason into something worth showing a person. */
export function resolveErrorMessage(reason) {
  return REASONS[reason] || REASONS.unreachable;
}

/**
 * Resolve a pasted link to the permanent sound URL to store.
 *
 * @param {string} input whatever was pasted, chat text around it is fine
 * @returns {Promise<{ok:boolean, canonical_url?:string, music_id?:string,
 *                    track?:string, artist?:string, reason?:string}>}
 *
 * @invariant Callers store `canonical_url` and discard the input. Storing what
 *            was pasted is the bug this module exists to remove.
 * @gotcha Never throws. A dead link is an ordinary outcome, and the caller needs
 *         to say so specifically rather than show a generic save failure.
 */
export async function resolveMusicUrl(input) {
  // Pull the URL out of the surrounding chat text BEFORE testing it. She pastes
  // whole messages ("use this one pls <url> by friday"), and trailing words
  // defeat the end-anchored music-id match, which sent an already-permanent
  // link on a pointless round trip.
  const m = String(input || '').match(/https?:\/\/[^\s"'<>)\]]+/);
  const raw = (m ? m[0] : String(input || '')).replace(/[.,;:!?)\]]+$/, '');

  // Already permanent: no round trip, just normalise off the query string.
  const direct = extractMusicId(raw);
  if (direct && !isShareLink(raw)) {
    return { ok: true, canonical_url: raw.split('?')[0].split('#')[0], music_id: direct };
  }

  try {
    const { data, error } = await supabase.functions.invoke('resolve-music-link', {
      body: { url: String(input).slice(0, 2000) },
    });
    if (error) return { ok: false, reason: 'unreachable' };
    return data || { ok: false, reason: 'unreachable' };
  } catch (_) {
    return { ok: false, reason: 'unreachable' };
  }
}
