import { format, parseISO } from 'date-fns';
import { supabase } from '../../lib/supabase';
import { useAuth } from '../../hooks/useAuth';
import { fmtDate, fmtMoney, isValidTikTokMusicUrl } from '../../utils/format';
import { openPopup } from '../../utils/openPopup';
import { useStatusOptions } from '../../contexts/StatusOptionsContext';
import { resolveStatusRow } from '../../utils/statusRow';
import { isSettledInvoice } from '../../utils/invoiceMath';
import { markPosted, outstandingPostRequirements } from '../../utils/markPosted';
import { mutate } from '../../utils/mutate';
import { resolveMusicUrl, resolveErrorMessage } from '../../utils/musicLink';
import { ViewsIcon, LikesIcon, CommentsIcon, SharesIcon, PlayIcon, CheckIcon } from '../shared/Icon';
import { useToast } from '../shared/Toast';
import { useConfirm } from '../shared/ConfirmDialog';
import Feedback from '../shared/Feedback';
import EmptyState from '../shared/EmptyState';
import Loading from '../shared/Loading';
import { humanizeReadError } from '../../utils/errors';
import MissingSounds from './MissingSounds';
import { campaignLabel } from '../../utils/campaignLabel';
import { activationProps } from '../../utils/rowActivation';
