/**
 * components/creator/MobilePostPage.js - the self-contained mobile (<=768px) post-a-video
 * screen. NOT a wrapper: it is the full surface a creator on a phone sees instead of
 * CreatorDashboard. Lists pending deliverables on active campaigns and marks one Posted.
 *
 * @gotcha a settled invoice's payment link is dropped from the fetch, or a creator can hand her
 *         agency a live checkout for money already received. "Settled" has ONE definition for
 *         this tier and the agency dashboard: utils/invoiceMath.js isSettledInvoice. Writing it
 *         locally as "status is Paid" is a different fact and disagrees on live rows.
 * @gotcha payment links are fetched in their own effect, not with the deliverable list, so a
 *         link on a COMPLETED campaign still shows. RLS scopes them to her own campaigns.
 * @gotcha a TikTok deliverable needs a valid sound URL before it can be marked Posted, and the
 *         video picker filters on campaign_start_date with no upper bound so a late post is
 *         still selectable.
 * @see components/creator/MissingSounds.js
 */

const PAGE = { minHeight: '100dvh', background: 'var(--black)', display: 'flex', flexDirection: 'column' };

function fmtD(d) {
  if (!d) return '';
  try { return format(parseISO(d.includes('T') ? d : d + 'T00:00:00'), 'MMM d'); } catch { return d; }
}

/**
 * Picks the posted video for a deliverable. For TikTok, loads the creator's
 * synced videos and excludes ones already assigned to another campaign's
 * deliverable. For any non-TikTok platform, renders a plain URL input instead.
 *
 * @param {function} onSelect - (url, postDate) called on selection; postDate is
 *        '' for the non-TikTok input path (no synced create_time available).
 * @gotcha Available-set filter keeps a video that THIS deliverable already
 *         points at (so re-opening a posted item is not silently empty), then
 *         drops any video whose id appears in another campaign's post_url.
 */
function MobileVideoPicker({ deliverable, platform, onSelect }) {
  const [videos, setVideos]       = useState([]);
  const [loading, setLoading]     = useState(true);
  const [selectedId, setSelectedId] = useState('');
  const campaign = deliverable.campaign;
  const isTikTok = (platform || '').toLowerCase() === 'tiktok';

  const [pickErr, setPickErr] = useState(null);
  // Why the list is empty, when the answer is not "the sync has not caught up". Both exits
  // below land on the empty state, and a creator with no handle on file must not be told to
  // wait for a sync that will never bring her anything.
  const [noHandle, setNoHandle] = useState(false);
  useEffect(() => { if (isTikTok) loadVideos(); else setLoading(false); }, []); // eslint-disable-line

  async function loadVideos() {
    setLoading(true);
    setPickErr(null);
    setNoHandle(false);
    const creatorId = campaign?.creator_profile_id;
    if (!creatorId) { setNoHandle(true); setLoading(false); return; }

    const { data: acct, error: acctErr } = await supabase
      .from('platform_accounts').select('username')
      .eq('profile_id', creatorId).eq('platform', 'tiktok').eq('is_active', true).single();
    // No handle means nothing to match her videos against, and an empty
    // picker reads as "you have posted nothing".
    if (acctErr) { setPickErr(humanizeReadError(acctErr)); setLoading(false); return; }
    if (!acct?.username) { setNoHandle(true); setLoading(false); return; }

    let q = supabase.from('tiktok_video_insights_view')
      .select('video_id, video_title, create_time, share_url, cover_image_url, total_play, total_like, total_comment, total_share')
      .eq('tiktok_username', acct.username)
      .order('create_time', { ascending: false });
    if (campaign.campaign_start_date) q = q.gte('create_time', campaign.campaign_start_date);
    const [videoRes, usedRes] = await Promise.all([
      q,
      supabase.from('campaign_deliverables')
        .select('post_url').neq('campaign_id', campaign.id).not('post_url', 'is', null),
    ]);
    // Same reason as the handle read above, one line further down: an empty picker reads as
    // "you have posted nothing" to a creator who posted this morning.
    if (videoRes.error) { setPickErr(humanizeReadError(videoRes.error)); setLoading(false); return; }
    // The used-URL read is load bearing, not a filter. It is the only thing keeping a video
    // that is already attached to ANOTHER campaign's deliverable out of this list, so without
    // it she can mark two deliverables live with one post and both campaigns bill for it.
    // Refusing to offer anything is the safe half of that trade.
    if (usedRes.error) { setPickErr(humanizeReadError(usedRes.error)); setLoading(false); return; }
    const allVideos = videoRes.data;
    const usedUrls = new Set((usedRes.data || []).map(r => r.post_url));

    const available = (allVideos || []).filter(v => {
      if (deliverable.post_url && deliverable.post_url.includes(v.video_id)) return true;
      return ![...usedUrls].some(url => url && url.includes(v.video_id));
    });

    const preSelected = available.find(v => deliverable.post_url?.includes(v.video_id));
    if (preSelected) setSelectedId(preSelected.video_id);

    setVideos(available);
    setLoading(false);
  }

  function handleChange(e) {
    const videoId = e.target.value;
    setSelectedId(videoId);
    if (!videoId) { onSelect('', ''); return; }
    const video = videos.find(v => v.video_id === videoId);
    if (!video) return;
    const url = video.share_url || `https://www.tiktok.com/video/${video.video_id}`;
    const postDate = video.create_time
      ? (video.create_time.includes('T') ? video.create_time.split('T')[0] : video.create_time)
      : '';
    onSelect(url, postDate);
  }

  const selectedVideo = videos.find(v => v.video_id === selectedId);

  // Non-TikTok: plain URL input
  if (!isTikTok) {
    return (
      <input aria-label="Link to your post"
        className="form-input"
        type="url"
        value={deliverable.post_url || ''}
        onChange={e => onSelect(e.target.value, '')}
        placeholder="https://..."
        maxLength={500}
        style={{ width: '100%', boxSizing: 'border-box', fontSize: 16 }}
      />
    );
  }

  if (loading) return <Loading style={{ fontSize: 13, padding: '8px 0' }}>Loading videos…</Loading>;
  // Error before Empty: "No unassigned videos" is a claim about what she posted.
  if (pickErr) return <div style={{ padding: '8px 0' }}><Feedback value={pickErr} /></div>;
  // Empty, and a dead end until P66: for a TikTok deliverable this picker is the only path to
  // a post_url, so a sentence with no control ends the job. It names what emptied it and
  // offers the control that undoes it, per .claude/rules/hub-ui.md.
  // Children, not `text`: a phone reads this paragraph at 13px, not the 12px of a one-liner.
  if (videos.length === 0) return (
    <EmptyState variant="note" style={{ padding: '8px 0' }}
      action={noHandle ? null
        : <button type="button" className="btn btn-secondary btn-sm" onClick={loadVideos}>Check again</button>}>
      <div style={{ color: 'var(--muted)', fontSize: 13, lineHeight: 1.5 }}>
        {noHandle
          ? 'No TikTok account is linked to your profile, so there is nothing to match your posts against. Ask Patrick to add it.'
          : <>
              Nothing to pick yet. This list holds your TikTok posts from the campaign start date
              on, minus any already attached to another campaign. They arrive on a sync that runs
              three times a day, around 6am, midday and 6pm Central, so a post from the last few
              hours may not have landed.
              {!campaign?.campaign_start_date && ' (No campaign start date set.)'}
            </>}
      </div>
    </EmptyState>
  );

  return (
    <>
      <select aria-label="Select the video you posted" className="form-select" value={selectedId} onChange={handleChange}
        style={{ width: '100%', boxSizing: 'border-box', fontSize: 16 }}>
        <option value="">Select a video…</option>
        {videos.map(v => (
          <option key={v.video_id} value={v.video_id}>
            {fmtD(v.create_time)} · {v.video_title ? (v.video_title.length > 55 ? v.video_title.slice(0, 55) + '…' : v.video_title) : v.video_id}
          </option>
        ))}
      </select>

      {selectedVideo && (
        <div style={{ marginTop: 16, borderRadius: 10, border: '1px solid var(--border)', overflow: 'hidden', background: 'var(--surface)' }}>
          {selectedVideo.cover_image_url && (
            <div
              {...activationProps(() => openPopup(selectedVideo.share_url))}
              /* The only content is an alt="" cover and a play glyph, so this control has
                 no name from its contents and has to state one. */
              aria-label={`Open this ${platform || 'video'} post`}
              style={{ cursor: 'pointer', position: 'relative' }}
            >
              <img
                src={selectedVideo.cover_image_url}
                alt=""
                style={{ width: '100%', maxHeight: 220, objectFit: 'cover', display: 'block' }}
              />
              <div style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'rgba(0,0,0,0.25)' }}>
                <div style={{ width: 44, height: 44, borderRadius: '50%', background: 'rgba(0,0,0,0.55)', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'var(--white)' }}>
                  <PlayIcon size={18} />
                </div>
              </div>
            </div>
          )}
          <div style={{ padding: '12px 14px' }}>
            <div style={{ fontSize: 13, fontWeight: 600, color: 'var(--white)', lineHeight: 1.4, marginBottom: 6 }}>
              {selectedVideo.video_title || selectedVideo.video_id}
            </div>
            <div style={{ fontSize: 12, color: 'var(--muted)', marginBottom: 8 }}>
              Posted {fmtD(selectedVideo.create_time)}
            </div>
            <div style={{ display: 'flex', gap: 14, fontSize: 12, color: 'var(--muted)', flexWrap: 'wrap' }}>
              {selectedVideo.total_play  != null && <span style={{ display: 'inline-flex', alignItems: 'center', gap: 4 }}><ViewsIcon size={12} /> {selectedVideo.total_play.toLocaleString()}</span>}
              {selectedVideo.total_like  != null && <span style={{ display: 'inline-flex', alignItems: 'center', gap: 4 }}><LikesIcon size={12} /> {selectedVideo.total_like.toLocaleString()}</span>}
              {selectedVideo.total_comment != null && <span style={{ display: 'inline-flex', alignItems: 'center', gap: 4 }}><CommentsIcon size={12} /> {selectedVideo.total_comment.toLocaleString()}</span>}
              {selectedVideo.total_share != null && <span style={{ display: 'inline-flex', alignItems: 'center', gap: 4 }}><SharesIcon size={12} /> {selectedVideo.total_share.toLocaleString()}</span>}
            </div>
          </div>
        </div>
      )}
    </>
  );
}

/**
 * The mobile post screen. Shows a deliverable list; tapping one opens the post
 * form (rendered in place of the list via the `selected` state, no router).
 *
 * @param {function} onShowFullSite - escape hatch to the desktop CreatorDashboard.
 * @gotcha load bails when the Active campaign / Posted deliverable status ids
 *         are not yet resolved from StatusOptions, rather than sending an
 *         invalid-uuid sentinel that PostgREST would 400 on.
 * @gotcha Posting the LAST pending deliverable auto-completes the campaign, but
 *         the invoice is NOT auto-created (performance deals settle days later;
 *         admin promotes it manually).
 */
export default function MobilePostPage({ onShowFullSite }) {
  const { options: statusOptions, loading: vocabLoading } = useStatusOptions();
  const activeDelivId  = (statusOptions.deliverable || []).find(o => o.value === 'Posted')?.id;
  const activeCampId   = (statusOptions.campaign    || []).find(o => o.value === 'Active')?.id;
  const { profile, signOut } = useAuth();
  const toast = useToast();
  const [deliverables, setDeliverables] = useState([]);
  const [loadErr, setLoadErr] = useState(null);
  const { loading, refreshing, begin, end } = useLoadState();
  const [selected, setSelected]         = useState(null);
  const [postUrl, setPostUrl]           = useState('');
  const [postDate, setPostDate]         = useState('');
  const [musicUrl, setMusicUrl]         = useState('');
  // Whether the sound field has been LEFT once. The red state waits for it, because the first
  // character typed is never a valid URL and accusing her of that is the whole defect. The
  // green state does not wait: confirming a paste the moment it parses is why the pair exists.
  const [musicBlurred, setMusicBlurred]  = useState(false);
  // Only set when the pasted link itself is the problem, usually already expired.
  const [musicError, setMusicError]     = useState(null);
  // Optional types only: her explicit "no sound was sent" answer.
  const [noSoundSent, setNoSoundSent]   = useState(false);

  // Does this deal's agency brief a sound? Absent agency or absent type defaults
  // to yes, which is the safer direction: it asks for something that may not
  // exist rather than silently dropping a compliance requirement.
  const musicRequired = selected?.musicRequired !== false;
  const typedMusic = musicUrl.trim();
  /**
   * Whether the sound question has been answered well enough to post.
   *
   * Required: a valid link, as before. Optional: either a valid link OR the
   * explicit "they didn't send one". Never a silent blank, because nothing
   * downstream can tell that apart from an unanswered row.
   */
  const canSubmitMusic = musicRequired
    ? isValidTikTokMusicUrl(typedMusic)
    : (typedMusic === '' ? noSoundSent : isValidTikTokMusicUrl(typedMusic));
  const [saving, setSaving]             = useState(false);
  const [saved, setSaved]               = useState(null);
  const [ftcChecked, setFtcChecked]     = useState(false);
  const [hashtagChecks, setHashtagChecks] = useState({});
  // The one gate. Post is disabled because this list is non-empty, never the other way
  // round, so a condition that greys the button always has a line naming it on screen.
  const confirm = useConfirm();
  /**
   * Leave the post screen, asking first if there is anything to lose.
   *
   * Both exits (Back and Cancel) reset the same five pieces of state, and one tap took the
   * URL, the sound, the FTC tick and every hashtag tick with it in silence.
   */
  async function leavePost() {
    const touched = !!postUrl || musicUrl.trim() !== '' || ftcChecked || noSoundSent
      || Object.values(hashtagChecks).some(Boolean);
    if (touched && !(await confirm({
      title: 'Leave without posting?',
      body: 'The video, sound and tick boxes you have filled in here will be cleared.',
      confirmLabel: 'Leave',
      cancelLabel: 'Keep filling it in',
      danger: true,
    }))) return;
    setSelected(null); setPostUrl(''); setPostDate(''); setMusicUrl('');
    setFtcChecked(false); setHashtagChecks({}); setNoSoundSent(false);
  }

  const outstanding = outstandingPostRequirements({
    deliverable: selected,
    postUrl,
    musicAnswered: canSubmitMusic,
    ftcChecked,
    hashtagChecks,
  });
  const [payLinks, setPayLinks]         = useState([]);
  // Held apart from an empty list, because an empty list is a positive claim: "you have
  // nothing to send your agency".
  const [payLinksErr, setPayLinksErr]   = useState(null);
  const [copiedLinkId, setCopiedLinkId] = useState(null);

  const load = useCallback(async () => {
    begin();
    setLoadErr(null);
    // Both id lookups depend on the vocabulary, and an unresolved id cannot be sent as a
    // sentinel: PostgREST 400s on an invalid uuid. Its ABSENCE is not an answer either. An
    // empty status group is not an empty deliverable list, so this bail must not land on the
    // empty state, which is the green check and "All caught up" on a screen with a post due.
    // `StatusVocabularyGate` catches a REFUSED status_options read; a group that came back
    // with no rows, or has not come back at all, arrives here.
    if (!activeCampId || !activeDelivId) {
      setDeliverables([]);
      // Still in flight: hold the branch `begin()` just raised, rather than flashing a claim
      // on every cold load. Settled and empty: say it cannot tell. Returning without `end()`
      // is the one deliberate exception to the hook's invariant, and it is safe because
      // `vocabLoading` is in this loader's deps, so the settle always gets a second pass.
      if (vocabLoading) return;
      setLoadErr({
        tone: 'error',
        title: "Couldn't check your deliverables",
        body: 'The status list did not load, so this screen cannot tell what is outstanding. Refresh and try again.',
      });
      end();
      return;
    }
    const { data: campaigns, error: campErr } = await supabase
      .from('campaigns')
      .select('id, campaign_name, display_name, campaign_start_date, campaign_end_date, creator_profile_id, agency:agencies(agency_type:agency_types(requires_music_brief))')
      .eq('status_id', activeCampId);
    // A refused read rendered "All caught up", which is the sentence the
    // incident put on her phone with a post due.
    if (campErr) { setLoadErr(humanizeReadError(campErr)); end(); return; }
    const campaignIds = (campaigns || []).map(c => c.id);
    if (campaignIds.length === 0) {
      setDeliverables([]);
      end();
      return;
    }
    const campaignMap = Object.fromEntries((campaigns || []).map(c => [c.id, { ...c, name: c.campaign_name }]));
    const { data: pending, error: pendErr } = await supabase
      .from('campaign_deliverables')
      .select('id, contracted_post_date, deliverable_details, draft_status_id, post_url, music_url, required_hashtags, ftc_disclosure, campaign_id, platform:platforms(name), deliverable_type:deliverable_types(name)')
      .in('campaign_id', campaignIds)
      // NOT `.neq(...)` alone: a bare neq is SQL `<>`, and `null <> uuid` is NULL,
      // not true, so every deliverable with no draft status was dropped from the
      // list and the creator was told "All caught up" with real work outstanding.
      .or(`draft_status_id.is.null,draft_status_id.neq.${activeDelivId}`)
      .order('contracted_post_date', { ascending: true, nullsFirst: false });
    if (pendErr) { setLoadErr(humanizeReadError(pendErr)); end(); return; }
    // Whether this deal's agency briefs a sound at all. A music promoter always
    // does; a brand or a concert promoter usually does not, and demanding one
    // from them made a brand post impossible to record without inventing a URL.
    // Absent type or absent agency defaults to required, the safer direction.
    setDeliverables((pending || []).map(d => {
      const camp = campaignMap[d.campaign_id] || null;
      return {
        ...d,
        campaign: camp,
        musicRequired: camp?.agency?.agency_type?.requires_music_brief !== false,
      };
    }));
    end();
    // vocabLoading is in here because with an empty group BOTH ids stay undefined forever, so
    // nothing else in this list ever changes and the page would hang on Loading.
  }, [activeCampId, activeDelivId, vocabLoading, begin, end]);

  useEffect(() => { load(); }, [load]);

  // Active payment links, fetched independently of the deliverable list so links on
  // already-completed campaigns still surface. RLS limits rows to owned campaigns.
  useEffect(() => {
    let alive = true;
    (async () => {
      const { data, error } = await supabase
        .from('campaign_payment_links')
        .select(`id, url, amount, campaign:campaigns(
                   id, campaign_name, display_name, campaign_start_date,
                   invoices(invoice_number, payment_status_id, is_in_kind),
                   campaign_deliverables(contracted_post_date))`)
        .eq('status', 'active')
        .order('created_at', { ascending: false });
      if (!alive) return;
      // Bound, for the reason the read directly above this one states: an empty picker reads
      // as "you have posted nothing", and an empty links block makes the same shape of claim
      // about money owed. A refusal must never reach either empty state.
      if (error) { setPayLinksErr(error); setPayLinks([]); return; }
      setPayLinksErr(null);
      if (!data) { setPayLinks([]); return; }

      // A link is not archived when its invoice is paid, so 2 of the 4 Mys could
      // see were for settled deals. The agency dashboard withholds a pay URL on a
      // settled invoice for exactly this reason; the creator side must match, or
      // she can hand her agency a live checkout for money already received.
      // isSettledInvoice is that one definition, and it takes a status VALUE, so
      // the id has to be resolved here first.
      // An empty payment group makes every lookup undefined, and isSettledInvoice reads that
      // as NOT settled, so a link for money already received is offered as still owed. The
      // gate branches on a REFUSED read only, so an empty group reaches here. P157, P200.
      if (!(statusOptions.payment || []).length) {
        setPayLinks([]);
        if (vocabLoading) return;
        setPayLinksErr({ tone: 'error', title: "Couldn't check which links are still owed", body: 'The status list did not load, so this screen cannot tell which of these are already paid.' });
        return;
      }
      const payStatusById = new Map((statusOptions.payment || []).map(o => [o.id, o.value]));
      const owed = data.filter(l => {
        const inv = (l.campaign?.invoices || [])[0];
        return inv && !isSettledInvoice(inv, payStatusById.get(inv.payment_status_id));
      });
      if (owed.length === 0) { setPayLinks([]); return; }

      // Each deal is named by its display name, the same string the hub tables and the
      // agency dashboard show. Do not resolve the sound here from yt_dlp_metadata: naming
      // a campaign has one home, in the database. @see utils/campaignLabel.js
      setPayLinks(owed.map(link => ({
        ...link,
        invoiceNumber: (link.campaign?.invoices || [])[0]?.invoice_number || null,
        dealDate: link.campaign?.campaign_start_date
          || (link.campaign?.campaign_deliverables || [])[0]?.contracted_post_date || null,
        label: campaignLabel(link.campaign),
      })));
    })();
    return () => { alive = false; };
  }, [statusOptions.payment, vocabLoading]);

  function copyPayLink(link) {
    navigator.clipboard.writeText(link.url).then(() => {
      setCopiedLinkId(link.id);
      setTimeout(() => setCopiedLinkId(null), 2000);
      toast.success('Payment link copied');
    });
  }

  /**
   * Mark the selected deliverable posted.
   *
   * @gotcha The sound is a HARD requirement only where the agency type briefs
   *         one. Demanding it of every TikTok deliverable makes a brand deal
   *         with no briefed sound unrecordable without inventing a URL. So the
   *         URL is optional there; the ANSWER is not. She either supplies the
   *         sound or confirms none was sent, and a silent blank is impossible.
   * @gotcha What she pastes is resolved to its permanent form first. A TikTok
   *         share link expires within days and leaves a dead reference.
   *         @see utils/musicLink.js
   */
  async function submit() {
    const isTikTok = selected.platform?.name?.toLowerCase() === 'tiktok';
    if (!postUrl) return;
    const typed = musicUrl.trim();
    if (isTikTok && !canSubmitMusic) return;

    // Before the resolve, not after it. The resolve is a network round trip, and with the
    // flag raised behind it the Post button stayed live for its whole duration: a second tap
    // ran submit() again on the same deliverable.
    setSaving(true);
    let resolvedMusic = null;
    if (isTikTok && typed) {
      const res = await resolveMusicUrl(typed);
      if (!res.ok) { setSaving(false); setMusicError(resolveErrorMessage(res.reason)); return; }
      resolvedMusic = res.canonical_url;
    }
    setMusicError(null);
    const campaignId = selected.campaign_id;
    const postedId = (statusOptions.deliverable || []).find(o => o.value === 'Posted')?.id || null;
    // Rides in the SAME statement as the status, so a sound and a post cannot half-land.
    const music = {};
    if (isTikTok && resolvedMusic) music.music_url = resolvedMusic;
    // No sound sent, on a type that does not brief one. Recorded as the answer
    // it is rather than left blank, which nothing downstream can interpret.
    if (isTikTok && !resolvedMusic && noSoundSent) music.music_brief_status = 'none_given';
    const { error: updateError } = await markPosted({
      supabase,
      deliverableId: selected.id,
      postedStatusId: postedId,
      postUrl,
      postDate,
      //: this path alone did not stamp posted_by. The column is creator-writable.
      userId: profile?.id,
      extra: music,
    });
    if (updateError) {
      setSaving(false);
      toast.error(updateError);
      return;
    }
    // Check if any deliverables in this campaign are still pending after this post.
    // postedId is guaranteed non-null by the sanity check above, but guard anyway.
    let remaining = null;
    let remainingErr = null;
    if (postedId) {
      const res = await supabase
        .from('campaign_deliverables')
        .select('id')
        .eq('campaign_id', campaignId)
        // Same null-vs-neq trap as load: a bare neq hides no-status rows, which
        // would auto-complete the campaign with a sibling deliverable still pending.
        .or(`draft_status_id.is.null,draft_status_id.neq.${postedId}`)
        .neq('id', selected.id)
        .limit(1);
      // Bound, because this read runs on the FAR SIDE of a write that already committed.
      // postgrest answers a refusal with `data: null`, so an unbound `remaining` fails the
      // `length === 0` guard and the campaign is left Active in silence.
      remainingErr = res.error || null;
      remaining = res.data;
    }
    // Read the label before the screen it came from is torn down.
    const campaignName = campaignLabel(selected.campaign);
    setSaved(selected.id);
    setSelected(null);
    setPostUrl('');
    setPostDate('');
    // Reported apart from the post, which succeeded, and named as the unknown it is: nothing
    // was skipped on purpose and nothing else on this surface would ever say so.
    if (remainingErr) {
      toast.error({
        title: 'Posted, but the campaign was not checked',
        body: 'Your post is saved. We could not check whether this campaign is now complete, so an admin may still need to close it.',
      });
    }
    if (remaining && remaining.length === 0) {
      // Last deliverable posted - auto-complete the campaign. Invoice is NOT auto-created;
      // admin creates / promotes it manually in CampaignsPage Invoice tab once the final
      // amount is known (performance-based deals settle days after completion).
      const completedId = (statusOptions?.campaign || []).find(o => o.value === 'Completed')?.id || null;
      if (completedId) {
        const { error: completeError } = await mutate(
          supabase.from('campaigns').update({ status_id: completedId }).eq('id', campaignId),
        );
        // Announced apart from the post, and reported apart from it. The deliverable is
        // already Posted by the time this runs, so neither outcome may read as a failed
        // post: a refusal here leaves a campaign sitting Active with everything delivered,
        // and nothing else on this surface would ever say so.
        if (completeError) toast.error(completeError);
        else toast.success(`${campaignName} is complete`);
      }
    }
    setSaving(false);
    load();
  }

  const creatorLabel = profile?.creator_name || profile?.full_name || '';

  // ── Post screen - rendered instead of the list ───────────────────────────────
  if (selected) {
    return (
      <main style={PAGE} id="main-content">
        {/* Top bar */}
        <div style={{ padding: '20px 20px 0', display: 'flex', alignItems: 'center', justifyContent: 'space-between', borderBottom: '1px solid var(--border)', paddingBottom: 16 }}>
          <button className="btn btn-ghost btn-sm" onClick={leavePost} style={{ color: 'var(--white)', fontSize: 13 }}>
            ← Back
          </button>
          <div style={{ fontFamily: 'var(--font-display)', fontSize: 20, letterSpacing: 1 }}>
            NYS<span style={{ color: 'var(--orange)' }}>T</span>ERYS
          </div>
          <div style={{ width: 60 }} />
        </div>

        {/* Content */}
        <div style={{ flex: 1, padding: '32px 24px 0', display: 'flex', flexDirection: 'column' }}>
          <div style={{ fontSize: 11, color: 'var(--orange)', textTransform: 'uppercase', letterSpacing: '0.12em', fontWeight: 700, marginBottom: 8 }}>
            {campaignLabel(selected.campaign)}
          </div>
          <div style={{ fontSize: 24, fontWeight: 700, color: 'var(--white)', marginBottom: 6, lineHeight: 1.2 }}>
            {selected.platform?.name} · {selected.deliverable_type?.name}
          </div>
          {selected.contracted_post_date && (
            <div style={{ fontSize: 14, color: 'var(--muted)', marginBottom: 36 }}>
              Due {fmtDate(selected.contracted_post_date)}
            </div>
          )}

          <div style={{ display: 'block', marginBottom: 8, fontSize: 11, fontWeight: 700, letterSpacing: '0.1em', textTransform: 'uppercase', color: 'var(--white)' }}>
            Select video
          </div>
          <MobileVideoPicker
            deliverable={selected}
            platform={selected.platform?.name || ''}
            onSelect={(url, date) => { setPostUrl(url); setPostDate(date); }}
          />

          {selected.ftc_disclosure !== 'none' && (
            <div style={{ marginTop: 28, padding: '14px 16px', borderRadius: 10, border: `1px solid ${selected.ftc_disclosure === 'required' ? 'rgba(255,92,0,0.4)' : 'var(--border)'}`, background: 'var(--surface)' }}>
              <div style={{ fontSize: 11, fontWeight: 700, letterSpacing: '0.1em', textTransform: 'uppercase', color: selected.ftc_disclosure === 'required' ? 'var(--orange)' : 'var(--muted)', marginBottom: 10 }}>
                FTC Disclosure{selected.ftc_disclosure === 'required' ? ' · Required' : ' · Recommended'}
              </div>
              <label style={{ display: 'flex', alignItems: 'flex-start', gap: 12, cursor: 'pointer' }}>
                <input
                  type="checkbox"
                  checked={ftcChecked}
                  onChange={e => setFtcChecked(e.target.checked)}
                  style={{ marginTop: 2, width: 18, height: 18, flexShrink: 0, accentColor: 'var(--orange)' }}
                />
                <span style={{ fontSize: 13, color: 'var(--white)', lineHeight: 1.5 }}>
                  I have disclosed this as a paid partnership using <strong>#ad</strong>, <strong>#sponsored</strong>, or TikTok's Paid Partnership label
                </span>
              </label>
            </div>
          )}

          {(selected.required_hashtags || []).length > 0 && (
            <div style={{ marginTop: 16, padding: '14px 16px', borderRadius: 10, border: '1px solid var(--border)', background: 'var(--surface)' }}>
              <div style={{ fontSize: 11, fontWeight: 700, letterSpacing: '0.1em', textTransform: 'uppercase', color: 'var(--orange)', marginBottom: 10 }}>
                Required Hashtags
              </div>
              <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
                {selected.required_hashtags.map(tag => (
                  <label key={tag} style={{ display: 'flex', alignItems: 'center', gap: 12, cursor: 'pointer' }}>
                    <input
                      type="checkbox"
                      checked={hashtagChecks[tag] || false}
                      onChange={e => setHashtagChecks(prev => ({ ...prev, [tag]: e.target.checked }))}
                      style={{ width: 18, height: 18, flexShrink: 0, accentColor: 'var(--orange)' }}
                    />
                    <span style={{ fontSize: 14, color: 'var(--white)', fontWeight: 500 }}>#{tag}</span>
                  </label>
                ))}
              </div>
            </div>
          )}

          {selected.platform?.name?.toLowerCase() === 'tiktok' && (
          <div style={{ marginTop: 28 }}>
            {/* The asterisk is the rule, so it tracks the rule. A music promoter
                always briefs a track; a brand usually does not, and marking it
                required there was why a brand post could not be recorded. */}
            <label style={{ display: 'block', marginBottom: 8, fontSize: 11, fontWeight: 700, letterSpacing: '0.1em', textTransform: 'uppercase', color: 'var(--white)' }}>
              Contracted Sound {musicRequired ? '*' : ''}
            </label>
            <input aria-label="Contracted sound"
              className="form-input"
              type="url"
              value={musicUrl}
              onChange={e => setMusicUrl(e.target.value)}
              onBlur={() => setMusicBlurred(true)}
              placeholder="https://www.tiktok.com/music/..."
              maxLength={500}
              autoComplete="off"
              autoCorrect="off"
              autoCapitalize="off"
              spellCheck={false}
              style={{ width: '100%', boxSizing: 'border-box', fontSize: 16 }}
            />
            {musicBlurred && musicUrl.trim() !== '' && !isValidTikTokMusicUrl(musicUrl.trim()) && (
              <div style={{ marginTop: 6, fontSize: 12, color: 'var(--red)', lineHeight: 1.4 }}>
                Must be a TikTok music link: tiktok.com/music/…
              </div>
            )}
            {isValidTikTokMusicUrl(musicUrl.trim()) && (
              <div style={{ marginTop: 6, fontSize: 12, color: 'var(--green)' }}>
                ✓ Valid TikTok sound
              </div>
            )}
            {musicError && (
              <div style={{ marginTop: 6, fontSize: 12, color: 'var(--red)', lineHeight: 1.4 }}>
                {musicError}
              </div>
            )}

            {/* Optional type: the URL may be absent, the answer may not. Without
                this she would leave the field blank and nothing downstream
                could tell "they sent none" from "she never got round to it". */}
            {!musicRequired && musicUrl.trim() === '' && (
              <label style={{ display: 'flex', alignItems: 'center', minHeight: 24, gap: 10, marginTop: 12, cursor: 'pointer' }}>
                <input
                  type="checkbox"
                  checked={noSoundSent}
                  onChange={e => setNoSoundSent(e.target.checked)}
                  style={{ width: 18, height: 18, flexShrink: 0, accentColor: 'var(--orange)' }}
                />
                <span style={{ fontSize: 13, color: 'var(--white)', lineHeight: 1.5 }}>
                  They didn&rsquo;t send a sound for this one
                </span>
              </label>
            )}
          </div>
          )}

          {/* The one classed element on this page, and deliberately: this box is shared with
              three desktop surfaces now, so it cannot stay inline like its neighbours.
              @see docs/DESIGN.md, which states the inline-styling exception for this file */}
          <OutstandingList items={outstanding} heading="Before you can post" style={{ marginTop: 24 }} />

          <div style={{ display: 'flex', gap: 12, marginTop: 24 }}>
            <button className="btn btn-ghost" style={{ flex: 1 }} onClick={leavePost}>
              Cancel
            </button>
            <SubmitButton saving={saving} className="btn btn-primary" style={{ flex: 2, fontSize: 15, fontWeight: 700 }} onClick={submit} disabled={saving || outstanding.length > 0}>Mark posted</SubmitButton>
          </div>
        </div>
      </main>
    );
  }

  // ── List screen ─────────────────────────────────────────────────────────────
  return (
    <main style={PAGE} id="main-content">

      {/* Header */}
      <div style={{ padding: '20px 20px 16px', borderBottom: '1px solid var(--border)' }}>
        <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', marginBottom: 12 }}>
          <div>
            <div style={{ fontFamily: 'var(--font-display)', fontSize: 26, letterSpacing: 1 }}>
              NYS<span style={{ color: 'var(--orange)' }}>T</span>ERYS
            </div>
            <h1 style={{ fontSize: 11, fontWeight: 400, color: 'var(--muted)', letterSpacing: '0.1em', textTransform: 'uppercase', margin: 0, marginTop: 2 }}>
              Post a video
            </h1>
          </div>
          <button
            className="btn btn-ghost btn-sm"
            onClick={onShowFullSite}
            style={{ fontSize: 11, color: 'var(--muted)', marginTop: 4 }}
          >
            Full site →
          </button>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          {creatorLabel && (
            <div style={{ fontSize: 13, color: 'var(--orange)', fontWeight: 700, letterSpacing: '0.04em' }}>
              {creatorLabel}
            </div>
          )}
          <button
            className="btn btn-ghost btn-sm"
            onClick={signOut}
            style={{ fontSize: 12, color: 'var(--white)', border: '1px solid var(--border)', marginLeft: 'auto' }}
          >
            Sign out
          </button>
        </div>
      </div>

      {/* Deliverable list */}
      <div style={{ flex: 1, padding: '20px 20px 32px', overflowY: 'auto' }}>

        <Refreshing on={refreshing} />
        {loading && <Loading style={{ textAlign: 'center', marginTop: 60, fontSize: 13 }} />}

        {!loading && loadErr && (
          <div style={{ marginTop: 24 }}>
            <Feedback value={loadErr} />
          </div>
        )}

        {!loading && !loadErr && deliverables.length === 0 && (
          // Children: `.empty-state-icon` dims a glyph to 30%, and this tick is the point.
          <EmptyState style={{ marginTop: 60, padding: 0 }}>
            <CheckIcon size={32} style={{ marginBottom: 12, color: 'var(--green)' }} />
            <div style={{ fontSize: 15, fontWeight: 600, marginBottom: 6 }}>All caught up</div>
            <div className="text-muted" style={{ fontSize: 13 }}>No pending deliverables on active campaigns.</div>
          </EmptyState>
        )}

        {!loading && !loadErr && deliverables.length > 0 && (
          <>
            <div style={{ fontSize: 12, color: 'var(--muted)', marginBottom: 14 }}>
              {deliverables.length} pending deliverable{deliverables.length !== 1 ? 's' : ''}
            </div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
              {deliverables.map(d => {
                // One resolver for every pill in the hub: by id only, inside the deliverable
                // group only, and NO pill when nothing matches. A positional fallback wears
                // whatever Workflow Setup sorted first, and the desktop tells this reader
                // nothing here either. @see utils/statusRow.js
                const status = resolveStatusRow(statusOptions, 'deliverable', { statusId: d.draft_status_id });
                const justSaved = saved === d.id;
                return (
                  <div
                    key={d.id}
                    {...activationProps(() => {
                      const checks = {};
                      (d.required_hashtags || []).forEach(tag => { checks[tag] = false; });
                      setSelected(d); setPostUrl(''); setPostDate(''); setMusicUrl(d.music_url || ''); setMusicError(null); setNoSoundSent(false);
                      setFtcChecked(false); setHashtagChecks(checks);
                    })}
                    style={{
                      background: 'var(--surface)',
                      border: `1px solid ${justSaved ? 'var(--green)' : 'var(--border)'}`,
                      borderRadius: 10,
                      padding: '14px 16px',
                      cursor: 'pointer',
                      transition: 'border-color 0.2s',
                    }}
                  >
                    <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 10 }}>
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <div style={{ fontSize: 14, fontWeight: 600, marginBottom: 4, lineHeight: 1.3 }}>
                          {campaignLabel(d.campaign)}
                        </div>
                        <div style={{ fontSize: 12, color: 'var(--muted)', display: 'flex', gap: 6, flexWrap: 'wrap' }}>
                          {d.platform?.name && <span>{d.platform.name}</span>}
                          {d.deliverable_type?.name && <span>· {d.deliverable_type.name}</span>}
                          {d.contracted_post_date && <span>· Due {fmtDate(d.contracted_post_date)}</span>}
                        </div>
                        {d.deliverable_details && (
                          <div style={{ fontSize: 11, color: 'var(--dim)', marginTop: 5, lineHeight: 1.4 }}>
                            {d.deliverable_details}
                          </div>
                        )}
                      </div>
                      {status && (
                        <div style={{
                          flexShrink: 0, background: status.bg_color, color: status.text_color,
                          fontSize: 10, fontWeight: 700,
                          letterSpacing: '0.06em', textTransform: 'uppercase',
                          padding: '3px 8px', borderRadius: 20,
                          whiteSpace: 'nowrap', marginTop: 2,
                        }}>
                          {status.label}
                        </div>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          </>
        )}

        {(payLinks.length > 0 || payLinksErr) && (
          <div style={{ marginTop: (loading || deliverables.length > 0) ? 32 : 0 }}>
            <div style={{ fontSize: 11, color: 'var(--muted)', letterSpacing: '0.1em', textTransform: 'uppercase', fontWeight: 700, marginBottom: 4 }}>
              Payment links
            </div>
            {payLinksErr ? <Feedback value={payLinksErr.body ? payLinksErr : humanizeReadError(payLinksErr)} /> : (<>
            {/* One line, not two: it has to teach both what the link is for and
                that the row itself is the button. The old copy said only the
                former and cost an extra line saying it. */}
            <div style={{ fontSize: 12, color: 'var(--dim)', marginBottom: 10, lineHeight: 1.4 }}>
              Tap to copy, then send to your agency to get paid by card.
            </div>
            {/* One tappable row per link, not a card: the whole row is the copy
                target, so there is no button chrome and the thumb target is the
                full width. Orange stays on the amount alone, which is the one
                thing worth drawing the eye. */}
            <div style={{ display: 'flex', flexDirection: 'column' }}>
              {payLinks.map((link, i) => {
                const copied = copiedLinkId === link.id;
                return (
                  <div
                    key={link.id}
                    role="button"
                    tabIndex={0}
                    onClick={() => copyPayLink(link)}
                    onKeyDown={e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); copyPayLink(link); } }}
                    style={{
                      display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', gap: 12,
                      padding: '13px 2px', cursor: 'pointer',
                      borderTop: i === 0 ? 'none' : '1px solid var(--border)',
                      transition: 'opacity 0.2s',
                    }}
                  >
                    <div style={{ minWidth: 0, flex: 1 }}>
                      <div title={copied ? 'Link copied' : (link.label !== '—' ? link.label : (link.dealDate ? fmtDate(link.dealDate) : 'Payment link'))} style={{ fontSize: 14, fontWeight: 600, color: 'var(--white)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                        {copied ? 'Link copied' : (link.label !== '—' ? link.label : (link.dealDate ? fmtDate(link.dealDate) : 'Payment link'))}
                      </div>
                      <div style={{ fontSize: 11, color: 'var(--dim)', marginTop: 3 }}>
                        {copied
                          ? 'Paste it to your agency'
                          : [link.sound && link.dealDate ? fmtDate(link.dealDate) : null, link.invoiceNumber]
                              .filter(Boolean).join(' · ')}
                      </div>
                    </div>
                    <div style={{ fontSize: 14, fontWeight: 700, color: copied ? 'var(--green)' : 'var(--orange)', flexShrink: 0 }}>
                      {copied ? <CheckIcon size={14} /> : fmtMoney(link.amount)}
                    </div>
                  </div>
                );
              })}
            </div>
            </>)}
          </div>
        )}

        <MissingSounds creatorName={creatorLabel} />
      </div>
    </main>
  );
}
